	private static boolean radixTranspose(long[] predicates, int[] roots, long[] runs, long[] predicateScratch,
			int[] rootScratch, long[] runScratch, int length, NativeCancellationToken cancellation) {
		long[] predicateInput = predicates;
		int[] rootInput = roots;
		long[] runInput = runs;
		long[] predicateOutput = predicateScratch;
		int[] rootOutput = rootScratch;
		long[] runOutput = runScratch;
		int[] counts = new int[RADIX_BUCKETS];
		int[] offsets = new int[RADIX_BUCKETS];
		for (int pass = 0; pass < RADIX_PASSES; pass++) {
			if (cancellation.isCancellationRequested()) {
				return false;
			}
			Arrays.fill(counts, 0);
			int shift = pass * RADIX_BITS;
			for (int i = 0; i < length; i++) {
				if ((i & CANCELLATION_POLL_MASK) == 0 && cancellation.isCancellationRequested()) {
					return false;
				}
				counts[(int) (predicateInput[i] >>> shift) & (RADIX_BUCKETS - 1)]++;
			}
			int next = 0;
			for (int bucket = 0; bucket < RADIX_BUCKETS; bucket++) {
				offsets[bucket] = next;
				next += counts[bucket];
			}
			for (int i = 0; i < length; i++) {
				if ((i & CANCELLATION_POLL_MASK) == 0 && cancellation.isCancellationRequested()) {
					return false;
				}
				int bucket = (int) (predicateInput[i] >>> shift) & (RADIX_BUCKETS - 1);
				int target = offsets[bucket]++;
				predicateOutput[target] = predicateInput[i];
				rootOutput[target] = rootInput[i];
				runOutput[target] = runInput[i];
			}
			long[] predicateSwap = predicateInput;
			predicateInput = predicateOutput;
			predicateOutput = predicateSwap;
			int[] rootSwap = rootInput;
			rootInput = rootOutput;
			rootOutput = rootSwap;
			long[] runSwap = runInput;
			runInput = runOutput;
			runOutput = runSwap;
		}
		if (predicateInput != predicates) {
			System.arraycopy(predicateInput, 0, predicates, 0, length);
			System.arraycopy(rootInput, 0, roots, 0, length);
			System.arraycopy(runInput, 0, runs, 0, length);
		}
		return !cancellation.isCancellationRequested();
	}

	private static int buildGroups(long[] sortedPredicates, int length, long[] predicateIds, int[] offsets,
			NativeCancellationToken cancellation) {
		int groups = 0;
		for (int incidence = 0; incidence < length; incidence++) {
			if ((incidence & CANCELLATION_POLL_MASK) == 0 && cancellation.isCancellationRequested()) {
				return -1;
			}
			if (incidence == 0 || sortedPredicates[incidence] != sortedPredicates[incidence - 1]) {
				predicateIds[groups] = sortedPredicates[incidence];
				offsets[groups] = incidence;
				groups++;
			}
		}
		offsets[groups] = length;
		return groups;
	}

	private static long rootMetadataBytes(int roots) {
		return Math.addExact(arrayBytes(roots, Long.BYTES),
				Math.addExact(arrayBytes((long) roots + 1L, Integer.BYTES), arrayBytes(roots, Integer.BYTES)));
	}

	private static long routePeakBytes(int roots, int incidences) {
		long metadata = rootMetadataBytes(roots);
		long residentIncidences = Math.addExact(
				Math.addExact(arrayBytes(incidences, Long.BYTES), arrayBytes(incidences, Integer.BYTES)),
				arrayBytes(incidences, Long.BYTES));
		long transposeScratch = residentIncidences;
		long groups = Math.addExact(arrayBytes(incidences, Long.BYTES),
				arrayBytes((long) incidences + 1L, Integer.BYTES));
		long radixWorkspace = Math.multiplyExact(2L, arrayBytes(RADIX_BUCKETS, Integer.BYTES));
		return Math.addExact(metadata,
				Math.addExact(residentIncidences, Math.addExact(transposeScratch,
						Math.addExact(groups, radixWorkspace))));
	}

	private static long routeResidentBytes(int roots, int incidences) {
		long rootState = Math.addExact(arrayBytes(roots, Long.BYTES),
				Math.addExact(arrayBytes((long) roots + 1L, Integer.BYTES), arrayBytes(roots, Integer.BYTES)));
		long incidencesState = Math.addExact(
				Math.addExact(arrayBytes(incidences, Long.BYTES), arrayBytes(incidences, Integer.BYTES)),
				arrayBytes(incidences, Long.BYTES));
		long groups = Math.addExact(arrayBytes(incidences, Long.BYTES),
				arrayBytes((long) incidences + 1L, Integer.BYTES));
		return Math.addExact(rootState, Math.addExact(incidencesState, groups));
	}

	private static long arrayBytes(long length, long width) {
		return Math.addExact(16L, Math.multiplyExact(length, width)) + 7L & -8L;
	}

